plan={'schemaVersion':1,'id':'scooby-lush-cave-r6-v1','status':'Authored illustration blocking plan; final anchors/art not yet approved','units':'relative layout units, not recovered measurements or Minecraft game coordinates','orientation':'North up. +X east/right, +Y south/down on plan; floorLevel illustrative gradual relative descent.','nodes':nodes,'walkingConnections':walk,'waterRoutes':water,'defaultInteriorRoute':['C0','C1','C2','C3','C4','C5','C6'],'outerRoute':['C0','F1','F2','C6'],'dayRoutes':{'1':['H0','F0','F1','C0','C1','C0','F1','F0','H0'],'2':['H0','F0','F1','C0','C1','C2','C3','C4','C5','C4','C3','C2','C1','C0','F1','F0','H0'],'3':['C0','C1','C2','C3','C4','C5','C6','C5','C4','C3','C2','C1','C0','F1','F2','C6','S1','L0','S1','C6','F2','F1','T0','F1','F0','H0'],'4':['C0','C1','C2','C3','C4','C5','C6','F2','F1','C0','C1','C0','F1','T0','F1','F0','H0']},'sightLines':['C0 sees C1 daylight floor, not blossom room or lake','C1 sees C2 arch and limited berries, not C3 pool','C2 reveals C3 dome only after north bend','C3 sees C4 stream lip, not C6 daylight directly','C4 sees flower-lit C5 arch; root rib occludes stream B briefly','C5 sees daylight at C6; leaf retrieval is on broad bank','Both openings connected outdoors by F2; Mama/PomPom do not teleport through scouting route'],'prohibitions':['stairs','ladder','constructed rescue ramp','deep pit dog rescue','literal voxel blocks','unexplained artificial cave lights','murals copied from the separate sacred cavern','unmapped chamber teleport','water flowing uphill','unattended magic shower']}
